import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

export default function EventPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [event, setEvent] = useState(null);

  useEffect(() => {
    fetch((process.env.REACT_APP_API || "http://localhost:4000") + `/api/dashboard/events/${id}`)
      .then((res) => res.json())
      .then(setEvent)
      .catch(console.error);
  }, [id]);

  if (!event) return <p>Loading event...</p>;

  return (
    <div className="section">
      <h2>{event.title}</h2>

      <img
        src={event.image}
        alt={event.title}
        style={{ width: "100%", borderRadius: 10, marginBottom: 20 }}
      />

      <p><strong>Date:</strong> {event.date}</p>
      <p><strong>Location:</strong> {event.location}</p>
      <p>{event.description}</p>

      <hr />

      <h3>To Register for This Event:</h3>
      <button onClick={() => navigate("/login")} className="btn">
        Login
      </button>
      <button onClick={() => navigate("/register")} className="btn">
        Register
      </button>
    </div>
  );
}
